-- Preserve the original seven services as data. Stable slugs/IDs make the import
-- idempotent; existing rows are never overwritten, including deleted services.
CREATE TABLE IF NOT EXISTS services (
    id UUID PRIMARY KEY,
    slug VARCHAR(180) NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    title VARCHAR(180) NOT NULL CHECK (length(btrim(title)) > 0),
    short_description VARCHAR(600) NOT NULL DEFAULT '',
    description TEXT NOT NULL DEFAULT '',
    icon VARCHAR(40) NOT NULL DEFAULT 'Shield',
    coordinate VARCHAR(80) NOT NULL DEFAULT '',
    image_url VARCHAR(600) NOT NULL DEFAULT '',
    image_path VARCHAR(500) NOT NULL DEFAULT '',
    action_href VARCHAR(600) NOT NULL DEFAULT '',
    presentation JSONB NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(presentation)='object'),
    seo JSONB NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(seo)='object'),
    status VARCHAR(16) NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','deleted')),
    sort_order INTEGER NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
    created_by UUID REFERENCES accounts_userprofile(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    published_at TIMESTAMPTZ,
    deleted_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS services_public_order_idx ON services(status,sort_order,created_at,id);

