INSERT INTO services(id,slug,title,short_description,description,icon,coordinate,action_href,presentation,status,sort_order,published_at,seo) VALUES ('10c48046-f87f-1286-267e-e3a737b6f457','seguridad','Seguridad','Vigilancia aérea perimetral con cámaras térmicas y ópticas, asesoramiento conforme a normativa AESA y experiencia en unidades especiales.','Nuestra misión es ofrecer un servicio de seguridad integral en tecnología dron, así como formación, a todas aquellas empresas y administraciones públicas que requieran un asesoramiento especializado y conforme a la normativa vigente.

También estamos capacitados para ofrecer, de acuerdo con las necesidades concretas de cada cliente, los mejores productos tecnológicos del mercado en materia de drones.

