INSERT INTO services(id,slug,title,short_description,description,icon,coordinate,action_href,presentation,status,sort_order,published_at,seo) VALUES ('893371ac-bbd7-0d6d-5a3a-702df425132a','fumigacion','Fumigación','Pulverización agrícola de precisión con drones, reduciendo hasta un 90% el consumo de productos fitosanitarios y optimizando cada hectárea.','La fumigación con drones representa un avance decisivo en la agricultura moderna. Nuestros equipos permiten aplicar productos fitosanitarios con una precisión milimétrica, reduciendo hasta un 90% el consumo respecto a métodos tradicionales.

Los sistemas de pulverización inteligente controlan el tamaño de gota y el caudal en tiempo real, adaptándose a las condiciones meteorológicas y al tipo de cultivo para maximizar la eficacia del tratamiento.

